INSERT INTO testimonials VALUES(1,'Gilbert Chaves','CEO','RetailPro Ltd.','Solfa Technologies rebuilt our online store and our conversion rate doubled within three months. Professional, responsive, and genuinely invested in our success.',NULL,5,1,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO testimonials VALUES(2,'Alina Rahman','Founder','UrbanWear','From branding to launch campaigns, the Solfa team handled everything. We could not have asked for a smoother experience.',NULL,5,2,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO testimonials VALUES(3,'Sakib Hossain','Director','MediCare Clinic','Our clinic now ranks on the first page for every key search term in our city. The SEO work paid for itself many times over.',NULL,5,3,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO faqs VALUES(1,'What services does Solfa Technologies offer?','We offer web development, SEO optimization, graphics design, digital marketing, social media strategy, and mobile app development - a complete digital growth stack under one roof.',1,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO faqs VALUES(2,'How long does a typical website project take?','A standard business website takes 3-6 weeks depending on scope. Larger platforms and custom applications are scoped individually with a clear timeline before we start.',2,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO faqs VALUES(3,'Do you work with startups and small businesses?','Absolutely. We build industry-specific strategies for businesses of all sizes, with flexible packages designed to fit startup budgets.',3,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO faqs VALUES(4,'How do you measure the success of a campaign?','Every engagement starts with agreed KPIs - traffic, rankings, leads, or revenue. You receive transparent monthly reports showing exactly what was done and what it achieved.',4,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO faqs VALUES(5,'Do you provide support after the project launches?','Yes. All projects include a support period, and we offer ongoing maintenance and growth retainers so your product keeps improving after launch.',5,1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO posts VALUES(1,'5 Signs Your Business Website Needs a Redesign','5-signs-your-business-website-needs-a-redesign','Slow load times, outdated design, and poor mobile experience quietly cost you customers. Here is how to know when it is time to rebuild.',replace('Slow load times, outdated design, and poor mobile experience quietly cost you customers. Here is how to know when it is time to rebuild.\n\nAt Solfa Technologies we help businesses make these decisions every day. This article walks through the key considerations, common mistakes, and a simple checklist you can apply to your own business right away.\n\nIf you would like a free consultation on this topic, get in touch with our team - we are always happy to help.','\n',char(10)),NULL,'Solfa Team','2026-07-06 09:41:52','2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO posts VALUES(2,'How Local SEO Helps Small Businesses Win Big','how-local-seo-helps-small-businesses-win-big','Local search is where buying decisions happen. Learn the fundamentals of ranking in your city and turning searches into store visits.',replace('Local search is where buying decisions happen. Learn the fundamentals of ranking in your city and turning searches into store visits.\n\nAt Solfa Technologies we help businesses make these decisions every day. This article walks through the key considerations, common mistakes, and a simple checklist you can apply to your own business right away.\n\nIf you would like a free consultation on this topic, get in touch with our team - we are always happy to help.','\n',char(10)),NULL,'Solfa Team','2026-06-29 09:41:52','2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO posts VALUES(3,'Choosing the Right Digital Marketing Channel in 2026','choosing-the-right-digital-marketing-channel-in-2026','Search, social, email, or video? A practical framework for deciding where your marketing budget will work hardest.',replace('Search, social, email, or video? A practical framework for deciding where your marketing budget will work hardest.\n\nAt Solfa Technologies we help businesses make these decisions every day. This article walks through the key considerations, common mistakes, and a simple checklist you can apply to your own business right away.\n\nIf you would like a free consultation on this topic, get in touch with our team - we are always happy to help.','\n',char(10)),NULL,'Solfa Team','2026-06-22 09:41:52','2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO jobs_openings VALUES(1,'Senior Laravel Developer','senior-laravel-developer','Dhaka (Hybrid)','Full Time','Negotiable','Build and maintain web applications for our clients using Laravel, MySQL, and modern front-end tooling.',replace('Build and maintain web applications for our clients using Laravel, MySQL, and modern front-end tooling.\n\nRequirements:\n- 2+ years of relevant professional experience\n- Strong communication and teamwork skills\n- Portfolio or work samples preferred\n\nTo apply, send your CV to careers@solfatechnologies.com with the job title in the subject line.','\n',char(10)),'2026-08-13 09:41:52',1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO jobs_openings VALUES(2,'UI/UX Designer','uiux-designer','Remote','Full Time','Negotiable','Design user interfaces for websites and mobile apps, from wireframes to polished, developer-ready designs.',replace('Design user interfaces for websites and mobile apps, from wireframes to polished, developer-ready designs.\n\nRequirements:\n- 2+ years of relevant professional experience\n- Strong communication and teamwork skills\n- Portfolio or work samples preferred\n\nTo apply, send your CV to careers@solfatechnologies.com with the job title in the subject line.','\n',char(10)),'2026-08-13 09:41:52',1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
INSERT INTO jobs_openings VALUES(3,'Digital Marketing Executive','digital-marketing-executive','Dhaka','Full Time','Negotiable','Plan and run performance marketing campaigns across Google and Meta platforms for our client portfolio.',replace('Plan and run performance marketing campaigns across Google and Meta platforms for our client portfolio.\n\nRequirements:\n- 2+ years of relevant professional experience\n- Strong communication and teamwork skills\n- Portfolio or work samples preferred\n\nTo apply, send your CV to careers@solfatechnologies.com with the job title in the subject line.','\n',char(10)),'2026-08-13 09:41:52',1,'2026-07-13 09:41:52','2026-07-13 09:41:52');
