PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "services" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "icon" varchar, "excerpt" text, "body" text, "image" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "projects" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "category" varchar, "client" varchar, "completed_at" date, "description" text, "image" varchar, "is_featured" tinyint(1) not null default '0', "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "testimonials" ("id" integer primary key autoincrement not null, "name" varchar not null, "position" varchar, "company" varchar, "quote" text not null, "avatar" varchar, "rating" integer not null default '5', "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "faqs" ("id" integer primary key autoincrement not null, "question" varchar not null, "answer" text not null, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "posts" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "excerpt" text, "body" text, "image" varchar, "author" varchar, "published_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "jobs_openings" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "location" varchar, "type" varchar not null default 'Full Time', "salary" varchar, "summary" text, "description" text, "deadline" date, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "contact_messages" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "phone" varchar, "subject" varchar, "message" text not null, "is_read" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "subscribers" ("id" integer primary key autoincrement not null, "name" varchar, "email" varchar not null, "created_at" datetime, "updated_at" datetime);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE UNIQUE INDEX "services_slug_unique" on "services" ("slug");
CREATE UNIQUE INDEX "projects_slug_unique" on "projects" ("slug");
CREATE UNIQUE INDEX "posts_slug_unique" on "posts" ("slug");
CREATE UNIQUE INDEX "jobs_openings_slug_unique" on "jobs_openings" ("slug");
CREATE UNIQUE INDEX "subscribers_email_unique" on "subscribers" ("email");
COMMIT;
